export const VERSION='1.0.0',STORAGE_KEY='qf-studio-chapter-07-v1';
export const STEPS=[['start','Set up a conditional model',10],['scenarios','State the assumptions',25],['forward','A forward payoff',25],['call','Payoff versus profit',30],['interpret','Read model outcomes',25],['lab','Change one assumption',35],['assessment','Independent transfer',20],['finish','Save a scenario card',10]];
export function payoffs(terminal,strike=100,premium=6){if([terminal,strike,premium].some(x=>typeof x!=='number'||!Number.isFinite(x)||x<0))throw Error('Use finite nonnegative prices, strike and premium.');const call=Math.max(terminal-strike,0);return {forward:terminal-strike,call,profit:call-premium};}
export const DATA=[70,90,100,106,120,140].map(terminal=>({terminal,...payoffs(terminal)}));
export function simulate(seed=42,spread=10,count=100){if(!Number.isInteger(seed)||seed<1||seed>999999||![5,10,20].includes(spread)||!Number.isInteger(count)||count<1||count>200)throw Error('Use seed 1–999999, spread 5, 10 or 20, and 1–200 paths.');let z=seed>>>0;const random=()=>{z=(Math.imul(1664525,z)+1013904223)>>>0;return z/4294967296;};return Array.from({length:count},(_,i)=>{let price=100;const returns=[],prices=[price];for(let j=0;j<3;j++){const r=Math.floor(random()*3)-1;returns.push(r*spread);price*=1+r*spread/100;prices.push(price);}return {path:i+1,returns,prices,terminal:price,...payoffs(price)};});}
const q=(id,title,answer,hint,critical=false)=>({id,title,answer,hint,critical,tolerance:.011,type:['i2', 'a7', 'a8'].includes(id)?'choice':'number'});
export const PRACTICE={scenarios:[q('s1','A three-period path starts at £100, then returns +10%, 0%, −10%. Terminal price (£)?',99,'100 × 1.10 × 1 × .90 = 99.'),q('s2','In the stated equally likely three-point model, one-period probability of a negative return (0–1)?',1/3,'Only one of −10%, 0%, +10% is negative. This is a model input, not an estimated market fact.')],forward:[q('f1','Long forward, K=100, terminal price=90. Payoff (£ per unit)?',-10,'90 − 100 = −10. A long forward can have a negative payoff.',true),q('f2','New case: K=95, terminal price=112. Long forward payoff (£)?',17,'112 − 95 = 17. There is no initial premium in this simplified example.')],call:[q('c1','Call strike £100, premium £6, terminal £104. Payoff (£)?',4,'max(104−100,0)=4. Premium is not subtracted from payoff.',true),q('c2','Same call: terminal £104. Undiscounted profit (£)?',-2,'Payoff 4 minus premium 6 = −2. In-the-money is not necessarily profitable.',true)],interpret:[q('i1','Call strike £100, premium £6. Terminal break-even price (£), ignoring financing?',106,'At 106, payoff is 6 and profit is zero.'),q('i2','Enter 1: more paths validate the return assumptions; 2: more paths describe the chosen model more precisely.',2,'Choose 2. Simulation precision cannot validate a model against markets.',true)]};
export const ASSESSMENTS=[q('a1','New path: £80 ×1.20 ×0.80. Terminal price (£)?',76.8,'80×1.2×.8=76.8.'),q('a2','Long forward K=80, terminal £76.80. Payoff (£)?',-3.2,'76.8−80=−3.2.',true),q('a3','Call K=80, premium £5, terminal £76.80. Payoff (£)?',0,'Exercise is optional: max(76.8−80,0)=0.',true),q('a4','That call’s undiscounted profit (£)?',-5,'0 payoff minus 5 premium.',true),q('a5','Call K=80, premium £5, terminal £84. Profit (£)?',-1,'Payoff 4 minus premium 5.'),q('a6','Call K=80, premium £5. Break-even terminal (£)?',85,'K plus premium, with no financing.'),q('a7','Enter 1: a seeded model is a guaranteed forecast; 2: outcomes are conditional on its assumptions.',2,'Choose 2; the model deliberately omits tails, dependence and changing distributions.',true),q('a8','Enter 1: repeat the same seed and assumptions to reproduce; 2: choose a different seed to guarantee identical paths.',1,'Same generator, seed and assumptions reproduce the exact paths.')];

export function check(q,raw){if(typeof raw==='boolean'||raw===null||String(raw??'').trim()==='')return false;const n=Number(raw);return Number.isFinite(n)&&Math.abs(n-q.answer)<=(q.type==='choice'?0:q.tolerance);}
export function grade(answers){const details=ASSESSMENTS.map(q=>({id:q.id,correct:check(q,answers[q.id]),critical:q.critical}));return {score:details.filter(d=>d.correct).length,passed:details.filter(d=>d.correct).length>=7&&details.filter(d=>d.critical).every(d=>d.correct),details};}
export const freshState=()=>({version:VERSION,fields:{},done:{},checked:{},practiceAttempts:[],runs:[],attempts:[]});
export function invalidate(s,id){for(const [step,qs]of Object.entries(PRACTICE))if(qs.some(q=>q.id===id)||id===step+'Reflection'||id===step+'Criteria'){delete s.done[step];delete s.checked[id];}if(id.startsWith('quiz-')||id==='revision'){delete s.done.assessment;s.fields.quizDirty='yes';}if(['prediction','seed','spread','hand','labReflection','labCriteria'].includes(id)){delete s.done.lab;if(id==='hand')s.fields.handVerified='';}if(id.startsWith('card'))delete s.done.finish;if(id==='setup')delete s.done.start;}
export function labEvidence(s){const run=s.runs.at(-1);return !!run&&run.prediction===s.fields.prediction&&run.seed===Number(s.fields.seed??42)&&run.spread===Number(s.fields.spread??10)&&s.runs.some(r=>r.seed===run.seed&&r.spread!==run.spread)&&check({answer:run.rows[0].terminal,tolerance:.011},s.fields.hand)&&s.fields.handVerified==='yes'&&(s.fields.labReflection||'').trim().length>=50&&s.fields.labCriteria==='yes';}
export function restoreState(raw){try{const s=JSON.parse(raw),record=v=>v&&typeof v==='object'&&!Array.isArray(v);if(s?.version!==VERSION||!record(s.fields)||Object.values(s.fields).some(v=>typeof v!=='string')||!record(s.done)||!record(s.checked)||Object.values(s.done).some(v=>typeof v!=='boolean')||Object.values(s.checked).some(v=>typeof v!=='boolean')||!Array.isArray(s.runs)||!Array.isArray(s.attempts))throw Error();const restored={...freshState(),fields:s.fields,practiceAttempts:(Array.isArray(s.practiceAttempts)?s.practiceAttempts:[]).filter(a=>record(a)&&typeof a.id==='string'&&typeof a.raw==='string'&&typeof a.correct==='boolean'&&typeof a.time==='string'),runs:s.runs.map(r=>{if(typeof r.prediction!=='string'||typeof r.time!=='string')throw Error();return {seed:r.seed,prediction:r.prediction,time:r.time,spread:r.spread,rows:simulate(r.seed,r.spread)};}),attempts:s.attempts.map(a=>{if(!record(a.answers)||Object.values(a.answers).some(v=>typeof v!=='string')||typeof a.time!=='string'||(a.revision!==undefined&&typeof a.revision!=='string'))throw Error();return {...a,...grade(a.answers)};})};/* Completion is re-derived from current evidence, never accepted from stored booleans. */for(const[step,qs]of Object.entries(PRACTICE)){for(const q of qs)if(s.checked[q.id]===true&&check(q,s.fields[q.id]))restored.checked[q.id]=true;if(qs.every(q=>restored.checked[q.id])&&(s.fields[step+'Reflection']||'').trim().length>=30&&s.fields[step+'Criteria']==='yes')restored.done[step]=true;}if(s.fields.setup==='yes')restored.done.start=true;const latest=restored.attempts.at(-1);if(latest?.passed&&s.fields.quizDirty!=='yes'&&latest.revision?.length>=30&&ASSESSMENTS.every(q=>latest.answers[q.id]===s.fields['quiz-'+q.id]))restored.done.assessment=true;if(['cardMethod','cardCheck','cardLimit'].every(k=>(s.fields[k]||'').trim().length>=30)&&s.fields.cardCriteria==='yes')restored.done.finish=true;if(labEvidence(restored))restored.done.lab=true;return restored;}catch{return freshState();}}
